256				if c.VSCSTarget != "" && c.VSCSTarget != VSCSTargetProduction {
257					data[f] = c.VSCSTarget
258				}
259			default:
260				sf := v.FieldByNameFunc(func(s string) bool {
261					return strings.EqualFold(f, s)
262				})
263				data[f] = sf.Interface()
264			}
265		}
266	
267		return data
268	}
