279	func (a *API) ListCodespaces(ctx context.Context, opts ListCodespacesOptions) (codespaces []*Codespace, err error) {
280		var (
281			perPage = 100
282			limit   = opts.Limit
283		)
284	
285		if limit > 0 && limit < 100 {
286			perPage = limit
287		}
288	
289		var (
290			listURL  string
291			spanName string
292		)
293	
294		if opts.RepoName != "" {
295			listURL = fmt.Sprintf("%s/repos/%s/codespaces?per_page=%d", a.githubAPI, opts.RepoName, perPage)
296			spanName = "/repos/*/codespaces"
297		} else if opts.OrgName != "" {
298			// the endpoints below can only be called by the organization admins
299			orgName := opts.OrgName
300			if opts.UserName != "" {
301				userName := opts.UserName
302				listURL = fmt.Sprintf("%s/orgs/%s/members/%s/codespaces?per_page=%d", a.githubAPI, orgName, userName, perPage)
303				spanName = "/orgs/*/members/*/codespaces"
304			} else {
305				listURL = fmt.Sprintf("%s/orgs/%s/codespaces?per_page=%d", a.githubAPI, orgName, perPage)
306				spanName = "/orgs/*/codespaces"
307			}
308		} else {
309			listURL = fmt.Sprintf("%s/user/codespaces?per_page=%d", a.githubAPI, perPage)
310			spanName = "/user/codespaces"
311		}
312	
313		for {
314			req, err := http.NewRequest(http.MethodGet, listURL, nil)
315			if err != nil {
316				return nil, fmt.Errorf("error creating request: %w", err)
317			}
318			a.setHeaders(req)
319	
320			resp, err := a.do(ctx, req, spanName)
321			if err != nil {
322				return nil, fmt.Errorf("error making request: %w", err)
323			}
324			defer resp.Body.Close()
325	
326			if resp.StatusCode != http.StatusOK {
327				return nil, api.HandleHTTPError(resp)
328			}
329	
330			var response struct {
331				Codespaces []*Codespace `json:"codespaces"`
332			}
333	
334			dec := json.NewDecoder(resp.Body)
335			if err := dec.Decode(&response); err != nil {
336				return nil, fmt.Errorf("error unmarshaling response: %w", err)
337			}
338	
339			nextURL := findNextPage(resp.Header.Get("Link"))
340			codespaces = append(codespaces, response.Codespaces...)
341	
342			if nextURL == "" || (limit > 0 && len(codespaces) >= limit) {
343				break
344			}
345	
346			if newPerPage := limit - len(codespaces); limit > 0 && newPerPage < 100 {
347				u, _ := url.Parse(nextURL)
348				q := u.Query()
349				q.Set("per_page", strconv.Itoa(newPerPage))
350				u.RawQuery = q.Encode()
351				listURL = u.String()
352			} else {
353				listURL = nextURL
354			}
355		}
356	
357		return codespaces, nil
358	}
