154	func formatCodespacesForSelect(codespaces []*api.Codespace, includeOwner bool) []string {
155	names := make([]string, len(codespaces))
156	
157	for i, apiCodespace := range codespaces {
158	cs := codespace{apiCodespace}
159	names[i] = cs.displayName(includeOwner)
160	}
161	
162	return names
163	}
