245	// displayName formats the codespace name for the interactive selector prompt.
246	func (c codespace) displayName(includeOwner bool) string {
247	branch := c.branchWithGitStatus()
248	displayName := c.DisplayName
249	
250	if displayName == "" {
251	displayName = c.Name
252	}
253	
254	description := fmt.Sprintf("%s (%s): %s", c.Repository.FullName, branch, displayName)
255	
256	if includeOwner {
257	description = fmt.Sprintf("%-15s %s", c.Owner.Login, description)
258	}
259	
260	return description
261	}
