263	// gitStatusDirty represents an unsaved changes status.
264	const gitStatusDirty = "*"
265	
266	// branchWithGitStatus returns the branch with a star
267	// if the branch is currently being worked on.
268	func (c codespace) branchWithGitStatus() string {
269	if c.hasUnsavedChanges() {
270	return c.GitStatus.Ref + gitStatusDirty
271	}
272	
273	return c.GitStatus.Ref
274	}
275	
276	// hasUnsavedChanges returns whether the environment has
277	// unsaved changes.
278	func (c codespace) hasUnsavedChanges() bool {
279	return c.GitStatus.HasUncommitedChanges || c.GitStatus.HasUnpushedChanges
280	}
281	
282	// running returns whether the codespace environment is running.
283	func (c codespace) running() bool {
284	return c.State == api.CodespaceStateAvailable
285	}
