19	func newStopCmd(app *App) *cobra.Command {
20	opts := &stopOptions{}
21	
22	stopCmd := &cobra.Command{
23	Use:   "stop",
24	Short: "Stop a running codespace",
25	Args:  noArgsConstraint,
26	RunE: func(cmd *cobra.Command, args []string) error {
27	if opts.orgName != "" && opts.codespaceName != "" && opts.userName == "" {
28	return cmdutil.FlagErrorf("using `--org` with `--codespace` requires `--user`")
29	}
30	return app.StopCodespace(cmd.Context(), opts)
31	},
32	}
33	stopCmd.Flags().StringVarP(&opts.codespaceName, "codespace", "c", "", "Name of the codespace")
34	stopCmd.Flags().StringVarP(&opts.orgName, "org", "o", "", "The `login` handle of the organization (admin-only)")
35	stopCmd.Flags().StringVarP(&opts.userName, "user", "u", "", "The `username` to stop codespace for (used with --org)")
36	
37	return stopCmd
38	}
39	
40	func (a *App) StopCodespace(ctx context.Context, opts *stopOptions) error {
41	codespaceName := opts.codespaceName
42	ownerName := opts.userName
43	
44	if codespaceName == "" {
45	a.StartProgressIndicatorWithLabel("Fetching codespaces")
46	codespaces, err := a.apiClient.ListCodespaces(ctx, api.ListCodespacesOptions{OrgName: opts.orgName, UserName: ownerName})
47	a.StopProgressIndicator()
48	if err != nil {
49	return fmt.Errorf("failed to list codespaces: %w", err)
50	}
51	
52	var runningCodespaces []*api.Codespace
53	for _, c := range codespaces {
54	cs := codespace{c}
55	if cs.running() {
56	runningCodespaces = append(runningCodespaces, c)
57	}
58	}
59	if len(runningCodespaces) == 0 {
60	return errors.New("no running codespaces")
61	}
62	
63	includeOwner := opts.orgName != ""
64	codespace, err := chooseCodespaceFromList(ctx, runningCodespaces, includeOwner)
65	if err != nil {
66	return fmt.Errorf("failed to choose codespace: %w", err)
67	}
68	codespaceName = codespace.Name
69	ownerName = codespace.Owner.Login
70	} else {
71	a.StartProgressIndicatorWithLabel("Fetching codespace")
72	
73	var c *api.Codespace
74	var err error
75	
76	if opts.orgName == "" {
77	c, err = a.apiClient.GetCodespace(ctx, codespaceName, false)
78	} else {
79	c, err = a.apiClient.GetOrgMemberCodespace(ctx, opts.orgName, ownerName, codespaceName)
80	}
81	a.StopProgressIndicator()
82	if err != nil {
83	return fmt.Errorf("failed to get codespace: %q: %w", codespaceName, err)
84	}
85	cs := codespace{c}
86	if !cs.running() {
87	return fmt.Errorf("codespace %q is not running", codespaceName)
88	}
89	}
90	
91	a.StartProgressIndicatorWithLabel("Stopping codespace")
92	defer a.StopProgressIndicator()
93	if err := a.apiClient.StopCodespace(ctx, codespaceName, opts.orgName, ownerName); err != nil {
94	return fmt.Errorf("failed to stop codespace: %w", err)
95	}
96	
97	return nil
98	}
