31	HttpClient: f.HttpClient,
32	}
33	
34	cmd := &cobra.Command{
35	Use:     "list",
36	Short:   "List releases in a repository",
37	Aliases: []string{"ls"},
38	Args:    cobra.NoArgs,
39	RunE: func(cmd *cobra.Command, args []string) error {
40	// support `-R, --repo` override
41	opts.BaseRepo = f.BaseRepo
42	
43	if runF != nil {
44	return runF(opts)
45	}
46	return listRun(opts)
47	},
48	}
