60	if err != nil {
61	return err
62	}
63	
64	baseRepo, err := opts.BaseRepo()
65	if err != nil {
66	return err
67	}
68	
69	releases, err := fetchReleases(httpClient, baseRepo, opts.LimitResults, opts.ExcludeDrafts, opts.ExcludePreReleases)
70	if err != nil {
71	return err
72	}
73	
74	if len(releases) == 0 && opts.Exporter == nil {
75	return cmdutil.NewNoResultsError("no releases found")
76	}
77	
78	if err := opts.IO.StartPager(); err == nil {
79	defer opts.IO.StopPager()
80	} else {
81	fmt.Fprintf(opts.IO.ErrOut, "failed to start pager: %v\n", err)
82	}
83	
84	if opts.Exporter != nil {
85	return opts.Exporter.Write(opts.IO, releases)
86	}
87	
88	table := tableprinter.New(opts.IO, tableprinter.WithHeader("Title", "Type", "Tag name", "Published"))
89	iofmt := opts.IO.ColorScheme()
90	for _, rel := range releases {
91	title := text.RemoveExcessiveWhitespace(rel.Name)
92	if title == "" {
93	title = rel.TagName
94	}
95	table.AddField(title)
96	
97	badge := ""
98	var badgeColor func(string) string
99	if rel.IsLatest {
100	badge = "Latest"
101	badgeColor = iofmt.Green
102	} else if rel.IsDraft {
103	badge = "Draft"
104	badgeColor = iofmt.Red
105	} else if rel.IsPrerelease {
106	badge = "Pre-release"
107	badgeColor = iofmt.Yellow
108	}
109	table.AddField(badge, tableprinter.WithColor(badgeColor))
110	
111	table.AddField(rel.TagName, tableprinter.WithTruncate(nil))
112	
113	pubDate := rel.PublishedAt
114	if rel.PublishedAt.IsZero() {
115	pubDate = rel.CreatedAt
116	}
117	table.AddTimeField(time.Now(), pubDate, iofmt.Gray)
118	table.EndRow()
119	}
120	err = table.Render()
121	if err != nil {
122	return err
123	}
124	
125	return nil
126	}
