247	func (pr *PullRequest) ChecksStatus() (summary PullRequestChecksStatus) {
248	if len(pr.StatusCheckRollup.Nodes) == 0 {
249	return
250	}
251	commit := pr.StatusCheckRollup.Nodes[0].Commit
252	for _, c := range commit.StatusCheckRollup.Contexts.Nodes {
253	state := c.State // StatusContext
254	if state == "" {
255	// CheckRun
256	if c.Status == "COMPLETED" {
257	state = c.Conclusion
258	} else {
259	state = c.Status
260	}
261	}
262	switch state {
263	case "SUCCESS", "NEUTRAL", "SKIPPED":
264	summary.Passing++
265	case "ERROR", "FAILURE", "CANCELLED", "TIMED_OUT", "ACTION_REQUIRED":
266	summary.Failing++
267	default: // "EXPECTED", "REQUESTED", "WAITING", "QUEUED", "PENDING", "IN_PROGRESS", "STALE"
268	summary.Pending++
269	}
270	summary.Total++
271	}
272	return
273	}
