287	// CreatePullRequest creates a pull request in a GitHub repository
288	func CreatePullRequest(client *Client, repo *Repository, params map[string]interface{}) (*PullRequest, error) {
289	query := `
290	mutation PullRequestCreate($input: CreatePullRequestInput!) {
291	createPullRequest(input: $input) {
292	pullRequest {
293	id
294	url
295	}
296	}
297	}`
298	
299	inputParams := map[string]interface{}{
300	"repositoryId": repo.ID,
301	}
302	for key, val := range params {
303	switch key {
304	case "title", "body", "draft", "baseRefName", "headRefName", "maintainerCanModify":
305	inputParams[key] = val
306	}
307	}
308	variables := map[string]interface{}{
309	"input": inputParams,
310	}
311	
312	result := struct {
313	CreatePullRequest struct {
314	PullRequest PullRequest
315	}
316	}{}
317	
318	err := client.GraphQL(repo.RepoHost(), query, variables, &result)
319	if err != nil {
320	return nil, err
321	}
322	pr := &result.CreatePullRequest.PullRequest
323	
324	// metadata parameters aren't currently available in `createPullRequest`,
325	// but they are in `updatePullRequest`
326	updateParams := make(map[string]interface{})
327	for key, val := range params {
328	switch key {
329	case "assigneeIds", "labelIds", "projectIds", "milestoneId":
330	if !isBlank(val) {
331	updateParams[key] = val
332	}
333	}
334	}
335	if len(updateParams) > 0 {
336	updateQuery := `
337	mutation PullRequestCreateMetadata($input: UpdatePullRequestInput!) {
338	updatePullRequest(input: $input) { clientMutationId }
339	}`
340	updateParams["pullRequestId"] = pr.ID
341	variables := map[string]interface{}{
342	"input": updateParams,
343	}
344	err := client.GraphQL(repo.RepoHost(), updateQuery, variables, &result)
345	if err != nil {
346	return pr, err
347	}
348	}
349	
350	// reviewers are requested in yet another additional mutation
351	reviewParams := make(map[string]interface{})
352	if ids, ok := params["userReviewerIds"]; ok && !isBlank(ids) {
353	reviewParams["userIds"] = ids
354	}
355	if ids, ok := params["teamReviewerIds"]; ok && !isBlank(ids) {
356	reviewParams["teamIds"] = ids
357	}
358	
359	//TODO: How much work to extract this into own method and use for create and edit?
360	if len(reviewParams) > 0 {
361	reviewQuery := `
362	mutation PullRequestCreateRequestReviews($input: RequestReviewsInput!) {
363	requestReviews(input: $input) { clientMutationId }
364	}`
365	reviewParams["pullRequestId"] = pr.ID
366	reviewParams["union"] = true
367	variables := map[string]interface{}{
368	"input": reviewParams,
369	}
370	err := client.GraphQL(repo.RepoHost(), reviewQuery, variables, &result)
371	if err != nil {
372	return pr, err
373	}
374	}
375	
376	return pr, nil
377	}
