65	func statusRun(opts *StatusOptions) error {
66	httpClient, err := opts.HttpClient()
67	if err != nil {
68	return err
69	}
70	
71	baseRepo, err := opts.BaseRepo()
72	if err != nil {
73	return err
74	}
75	
76	var currentBranch string
77	var currentPRNumber int
78	var currentPRHeadRef string
79	
80	if !opts.HasRepoOverride {
81	currentBranch, err = opts.Branch()
82	if err != nil && !errors.Is(err, git.ErrNotOnAnyBranch) {
83	return fmt.Errorf("could not query for pull request for current branch: %w", err)
84	}
85	
86	remotes, _ := opts.Remotes()
87	currentPRNumber, currentPRHeadRef, err = prSelectorForCurrentBranch(baseRepo, currentBranch, remotes)
88	if err != nil {
89	return fmt.Errorf("could not query for pull request for current branch: %w", err)
90	}
91	}
92	
93	options := requestOptions{
94	Username:  "@me",
95	CurrentPR: currentPRNumber,
96	HeadRef:   currentPRHeadRef,
97	}
98	if opts.Exporter != nil {
99	options.Fields = opts.Exporter.Fields()
100	}
101	prPayload, err := pullRequestStatus(httpClient, baseRepo, options)
102	if err != nil {
103	return err
104	}
105	
106	err = opts.IO.StartPager()
107	if err != nil {
108	fmt.Fprintf(opts.IO.ErrOut, "error starting pager: %v\n", err)
109	}
110	defer opts.IO.StopPager()
111	
112	if opts.Exporter != nil {
113	data := map[string]interface{}{
114	"currentBranch": nil,
115	"createdBy":     prPayload.ViewerCreated.PullRequests,
116	"needsReview":   prPayload.ReviewRequested.PullRequests,
117	}
118	if prPayload.CurrentPR != nil {
119	data["currentBranch"] = prPayload.CurrentPR
120	}
121	return opts.Exporter.Write(opts.IO, data)
122	}
123	
124	out := opts.IO.Out
125	cs := opts.IO.ColorScheme()
126	
127	fmt.Fprintln(out, "")
128	fmt.Fprintf(out, "Relevant pull requests in %s\n", ghrepo.FullName(baseRepo))
129	fmt.Fprintln(out, "")
130	
131	shared.PrintHeader(opts.IO, "Current branch")
132	currentPR := prPayload.CurrentPR
133	if currentPR != nil && currentPR.State != "OPEN" && prPayload.DefaultBranch == currentBranch {
134	currentPR = nil
135	}
136	if currentPR != nil {
137	printPrs(opts.IO, 1, *currentPR)
138	} else if currentPRHeadRef == "" {
139	shared.PrintMessage(opts.IO, "  There is no current branch")
140	} else {
141	shared.PrintMessage(opts.IO, fmt.Sprintf("  There is no pull request associated with %s", cs.Cyan("["+currentPRHeadRef+"]")))
142	}
143	fmt.Fprintln(out)
144	
145	shared.PrintHeader(opts.IO, "Created by you")
146	if prPayload.ViewerCreated.TotalCount > 0 {
147	printPrs(opts.IO, prPayload.ViewerCreated.TotalCount, prPayload.ViewerCreated.PullRequests...)
148	} else {
149	shared.PrintMessage(opts.IO, "  You have no open pull requests")
150	}
151	fmt.Fprintln(out)
152	
153	shared.PrintHeader(opts.IO, "Requesting a code review from you")
154	if prPayload.ReviewRequested.TotalCount > 0 {
155	printPrs(opts.IO, prPayload.ReviewRequested.TotalCount, prPayload.ReviewRequested.PullRequests...)
156	} else {
157	shared.PrintMessage(opts.IO, "  You have no pull requests to review")
158	}
159	fmt.Fprintln(out)
