164	func prSelectorForCurrentBranch(baseRepo ghrepo.Interface, prHeadRef string, rem context.Remotes) (prNumber int, selector string, err error) {
165	selector = prHeadRef
166	branchConfig := git.ReadBranchConfig(prHeadRef)
167	
168	// the branch is configured to merge a special PR head ref
169	prHeadRE := regexp.MustCompile(`^refs/pull/(\d+)/head$`)
170	if m := prHeadRE.FindStringSubmatch(branchConfig.MergeRef); m != nil {
171	prNumber, _ = strconv.Atoi(m[1])
172	return
173	}
174	
175	var branchOwner string
176	if branchConfig.RemoteURL != nil {
177	// the branch merges from a remote specified by URL
178	if r, err := ghrepo.FromURL(branchConfig.RemoteURL); err == nil {
179	branchOwner = r.RepoOwner()
180	}
181	} else if branchConfig.RemoteName != "" {
182	// the branch merges from a remote specified by name
183	if r, err := rem.FindByName(branchConfig.RemoteName); err == nil {
184	branchOwner = r.RepoOwner()
185	}
186	}
187	
188	if branchOwner != "" {
189	if strings.HasPrefix(branchConfig.MergeRef, "refs/heads/") {
190	selector = strings.TrimPrefix(branchConfig.MergeRef, "refs/heads/")
191	}
192	// prepend `OWNER:` if this branch is pushed to a fork
193	if !strings.EqualFold(branchOwner, baseRepo.RepoOwner()) {
194	selector = fmt.Sprintf("%s:%s", branchOwner, selector)
195	}
196	}
197	
198	return
199	}
