211	func printPrs(io *iostreams.IOStreams, totalCount int, prs ...api.PullRequest) {
212	w := io.Out
213	cs := io.ColorScheme()
214	
215	for _, pr := range prs {
216	prNumber := fmt.Sprintf("#%d", pr.Number)
217	
218	prStateColorFunc := cs.ColorFromString(shared.ColorForPRState(pr))
219	
220	fmt.Fprintf(w, "  %s  %s %s", prStateColorFunc(prNumber), text.Truncate(50, text.RemoveExcessiveWhitespace(pr.Title)), cs.Cyan("["+pr.HeadLabel()+"]"))
221	
222	checks := pr.ChecksStatus()
223	reviews := pr.ReviewStatus()
224	
225	if pr.State == "OPEN" {
226	reviewStatus := reviews.ChangesRequested || reviews.Approved || reviews.ReviewRequired
227	if checks.Total > 0 || reviewStatus {
228	// show checks & reviews on their own line
229	fmt.Fprintf(w, "\n  ")
230	}
231	
232	if checks.Total > 0 {
233	var summary string
234	if checks.Failing > 0 {
235	if checks.Failing == checks.Total {
236	summary = cs.Red("× All checks failing")
237	} else {
238	summary = cs.Redf("× %d/%d checks failing", checks.Failing, checks.Total)
239	}
240	} else if checks.Pending > 0 {
241	summary = cs.Yellow("- Checks pending")
242	} else if checks.Passing == checks.Total {
243	summary = cs.Green("✓ Checks passing")
244	}
245	fmt.Fprint(w, summary)
246	}
247	
248	if checks.Total > 0 && reviewStatus {
249	// add padding between checks & reviews
250	fmt.Fprint(w, " ")
251	}
252	
253	if reviews.ChangesRequested {
254	fmt.Fprint(w, cs.Red("+ Changes requested"))
255	} else if reviews.ReviewRequired {
256	fmt.Fprint(w, cs.Yellow("- Review required"))
257	} else if reviews.Approved {
258	numRequiredApprovals := pr.BaseRef.BranchProtectionRule.RequiredApprovingReviewCount
259	gotApprovals := totalApprovals(&pr)
260	s := fmt.Sprintf("%d", gotApprovals)
261	if numRequiredApprovals > 0 {
262	s = fmt.Sprintf("%d/%d", gotApprovals, numRequiredApprovals)
263	}
264	fmt.Fprint(w, cs.Green(fmt.Sprintf("✓ %s Approved", s)))
265	}
266	
267	if pr.BaseRef.BranchProtectionRule.RequiresStrictStatusChecks {
268	switch pr.MergeStateStatus {
269	case "BEHIND":
270	fmt.Fprintf(w, " %s", cs.Yellow("- Not up to date"))
271	case "UNKNOWN", "DIRTY":
272	// do not print anything
273	default:
274	fmt.Fprintf(w, " %s", cs.Green("✓ Up to date"))
275	}
276	}
277	
278	} else {
279	fmt.Fprintf(w, " - %s", shared.StateTitleWithColor(cs, pr))
280	}
281	
282	fmt.Fprint(w, "\n")
283	}
284	remaining := totalCount - len(prs)
285	if remaining > 0 {
286	fmt.Fprintf(w, cs.Gray("  And %d more\n"), remaining)
287	}
288	}
