167	func printHumanPrPreview(opts *ViewOptions, pr *api.PullRequest) error {
168	out := opts.IO.Out
169	cs := opts.IO.ColorScheme()
170	
171	// Header (Title and State)
172	fmt.Fprintf(out, "%s #%d\n", cs.Bold(pr.Title), pr.Number)
173	fmt.Fprintf(out,
174	"%s • %s wants to merge %s into %s from %s • %s • %s %s \n",
175	shared.StateTitleWithColor(cs, *pr),
176	pr.Author.Login,
177	text.Pluralize(pr.Commits.TotalCount, "commit"),
178	pr.BaseRefName,
179	pr.HeadRefName,
180	text.FuzzyAgo(opts.Now(), pr.CreatedAt),
181	cs.Green("+"+strconv.Itoa(pr.Additions)),
182	cs.Red("-"+strconv.Itoa(pr.Deletions)),
183	)
184	
185	// Reactions
186	if reactions := shared.ReactionGroupList(pr.ReactionGroups); reactions != "" {
187	fmt.Fprint(out, reactions)
188	fmt.Fprintln(out)
189	}
190	
191	// Metadata
192	if reviewers := prReviewerList(*pr, cs); reviewers != "" {
193	fmt.Fprint(out, cs.Bold("Reviewers: "))
194	fmt.Fprintln(out, reviewers)
195	}
196	if assignees := prAssigneeList(*pr); assignees != "" {
197	fmt.Fprint(out, cs.Bold("Assignees: "))
198	fmt.Fprintln(out, assignees)
199	}
200	if labels := prLabelList(*pr, cs); labels != "" {
201	fmt.Fprint(out, cs.Bold("Labels: "))
202	fmt.Fprintln(out, labels)
203	}
204	if projects := prProjectList(*pr); projects != "" {
205	fmt.Fprint(out, cs.Bold("Projects: "))
206	fmt.Fprintln(out, projects)
207	}
208	if pr.Milestone != nil {
209	fmt.Fprint(out, cs.Bold("Milestone: "))
210	fmt.Fprintln(out, pr.Milestone.Title)
211	}
212	
213	// Body
214	var md string
215	var err error
216	if pr.Body == "" {
217	md = fmt.Sprintf("\n  %s\n\n", cs.Gray("No description provided"))
218	} else {
219	md, err = markdown.Render(pr.Body,
220	markdown.WithTheme(opts.IO.TerminalTheme()),
221	markdown.WithWrap(opts.IO.TerminalWidth()))
222	if err != nil {
223	return err
224	}
225	}
226	fmt.Fprintf(out, "\n%s\n", md)
227	
228	// Reviews and Comments
229	if pr.Comments.TotalCount > 0 || pr.Reviews.TotalCount > 0 {
230	preview := !opts.Comments
231	comments, err := shared.CommentList(opts.IO, pr.Comments, pr.DisplayableReviews(), preview)
232	if err != nil {
233	return err
234	}
235	fmt.Fprint(out, comments)
236	}
237	
238	// Footer
239	fmt.Fprintf(out, cs.Gray("View this pull request on GitHub: %s\n"), pr.URL)
240	
241	return nil
242	}
