244	const (
245	requestedReviewState        = "REQUESTED" // This is our own state for review request
246	approvedReviewState         = "APPROVED"
247	changesRequestedReviewState = "CHANGES_REQUESTED"
248	commentedReviewState        = "COMMENTED"
249	dismissedReviewState        = "DISMISSED"
250	pendingReviewState          = "PENDING"
251	)
252	
253	type reviewerState struct {
254	Name  string
255	State string
256	}
257	
258	// formattedReviewerState formats a reviewerState with state color
259	func formattedReviewerState(cs *iostreams.ColorScheme, reviewer *reviewerState) string {
260	var displayState string
261	switch reviewer.State {
262	case requestedReviewState:
263	displayState = cs.Yellow("Requested")
264	case approvedReviewState:
265	displayState = cs.Green("Approved")
266	case changesRequestedReviewState:
267	displayState = cs.Red("Changes requested")
268	case commentedReviewState, dismissedReviewState:
269	// Show "DISMISSED" review as "COMMENTED", since "dismissed" only makes
270	// sense when displayed in an events timeline but not in the final tally.
271	displayState = "Commented"
272	default:
273	displayState = text.Title(reviewer.State)
274	}
275	
276	return fmt.Sprintf("%s (%s)", reviewer.Name, displayState)
277	}
278	
279	// prReviewerList generates a reviewer list with their last state
280	func prReviewerList(pr api.PullRequest, cs *iostreams.ColorScheme) string {
281	reviewerStates := parseReviewers(pr)
282	reviewers := make([]string, 0, len(reviewerStates))
283	
284	sortReviewerStates(reviewerStates)
285	
286	for _, reviewer := range reviewerStates {
287	reviewers = append(reviewers, formattedReviewerState(cs, reviewer))
288	}
289	
290	reviewerList := strings.Join(reviewers, ", ")
291	
292	return reviewerList
293	}
294	
295	const ghostName = "ghost"
296	
297	// parseReviewers parses given Reviews and ReviewRequests
298	func parseReviewers(pr api.PullRequest) []*reviewerState {
299	reviewerStates := make(map[string]*reviewerState)
300	
301	for _, review := range pr.Reviews.Nodes {
302	if review.Author.Login != pr.Author.Login {
303	name := review.Author.Login
304	if name == "" {
305	name = ghostName
306	}
307	reviewerStates[name] = &reviewerState{
308	Name:  name,
309	State: review.State,
310	}
311	}
312	}
313	
314	// Overwrite reviewer's state if a review request for the same reviewer exists.
315	for _, reviewRequest := range pr.ReviewRequests.Nodes {
316	name := reviewRequest.RequestedReviewer.LoginOrSlug()
317	reviewerStates[name] = &reviewerState{
318	Name:  name,
319	State: requestedReviewState,
320	}
321	}
322	
323	// Convert map to slice for ease of sort
324	result := make([]*reviewerState, 0, len(reviewerStates))
325	for _, reviewer := range reviewerStates {
326	if reviewer.State == pendingReviewState {
327	continue
328	}
329	result = append(result, reviewer)
330	}
331	
332	return result
333	}
334	
335	// sortReviewerStates puts completed reviews before review requests and sorts names alphabetically
336	func sortReviewerStates(reviewerStates []*reviewerState) {
337	sort.Slice(reviewerStates, func(i, j int) bool {
338	if reviewerStates[i].State == requestedReviewState &&
339	reviewerStates[j].State != requestedReviewState {
340	return false
341	}
342	if reviewerStates[j].State == requestedReviewState &&
343	reviewerStates[i].State != requestedReviewState {
344	return true
345	}
346	
347	return reviewerStates[i].Name < reviewerStates[j].Name
348	})
349	}
