351	func prAssigneeList(pr api.PullRequest) string {
352	if len(pr.Assignees.Nodes) == 0 {
353	return ""
354	}
355	
356	AssigneeNames := make([]string, 0, len(pr.Assignees.Nodes))
357	for _, assignee := range pr.Assignees.Nodes {
358	AssigneeNames = append(AssigneeNames, assignee.Login)
359	}
360	
361	list := strings.Join(AssigneeNames, ", ")
362	if pr.Assignees.TotalCount > len(pr.Assignees.Nodes) {
363	list += ", …"
364	}
