390	projectNames := make([]string, 0, len(pr.ProjectCards.Nodes))
391	for _, project := range pr.ProjectCards.Nodes {
392	colName := project.Column.Name
393	if colName == "" {
394	colName = "Awaiting triage"
395	}
396	projectNames = append(projectNames, fmt.Sprintf("%s (%s)", project.Project.Name, colName))
397	}
398	
399	list := strings.Join(projectNames, ", ")
400	if pr.ProjectCards.TotalCount > len(pr.ProjectCards.Nodes) {
401	list += ", …"
402	}
403	return list
404	}
