202	func editRun(ctx context.Context, opts *EditOptions) error {
203		repo := opts.Repository
204	
205		if opts.InteractiveMode {
206			detector := opts.Detector
207			if detector == nil {
208				cachedClient := api.NewCachedHTTPClient(opts.HTTPClient, time.Hour*24)
209				detector = fd.NewDetector(cachedClient, repo.RepoHost())
210			}
211			repoFeatures, err := detector.RepositoryFeatures()
212			if err != nil {
213				return err
214			}
215	
216			apiClient := api.NewClientFromHTTP(opts.HTTPClient)
217			fieldsToRetrieve := []string{
218				"defaultBranchRef",
219				"deleteBranchOnMerge",
220				"description",
221				"hasIssuesEnabled",
222				"hasProjectsEnabled",
223				"hasWikiEnabled",
224				// TODO: GitHub Enterprise Server does not support has_discussions yet
225				// "hasDiscussionsEnabled",
226				"homepageUrl",
227				"isInOrganization",
228				"isTemplate",
229				"mergeCommitAllowed",
230				"rebaseMergeAllowed",
231				"repositoryTopics",
232				"stargazerCount",
233				"squashMergeAllowed",
234				"watchers",
235			}
236			if repoFeatures.VisibilityField {
237				fieldsToRetrieve = append(fieldsToRetrieve, "visibility")
238			}
239			if repoFeatures.AutoMerge {
240				fieldsToRetrieve = append(fieldsToRetrieve, "autoMergeAllowed")
241			}
242	
243			opts.IO.StartProgressIndicator()
244			fetchedRepo, err := api.FetchRepository(apiClient, opts.Repository, fieldsToRetrieve)
245			opts.IO.StopProgressIndicator()
246			if err != nil {
247				return err
248			}
249			err = interactiveRepoEdit(opts, fetchedRepo)
250			if err != nil {
251				return err
252			}
253		}
254	
255		if opts.Edits.SecurityAndAnalysis != nil {
256			apiClient := api.NewClientFromHTTP(opts.HTTPClient)
257			repo, err := api.FetchRepository(apiClient, opts.Repository, []string{"viewerCanAdminister"})
258			if err != nil {
259				return err
260			}
261			if !repo.ViewerCanAdminister {
262				return fmt.Errorf("you do not have sufficient permissions to edit repository security and analysis features")
263			}
264		}
265	
266		apiPath := fmt.Sprintf("repos/%s/%s", repo.RepoOwner(), repo.RepoName())
267	
268		body := &bytes.Buffer{}
269		enc := json.NewEncoder(body)
270		if err := enc.Encode(opts.Edits); err != nil {
271			return err
272		}
273	
274		g := errgroup.Group{}
275	
276		if body.Len() > 3 {
277			g.Go(func() error {
278				apiClient := api.NewClientFromHTTP(opts.HTTPClient)
279				_, err := api.CreateRepoTransformToV4(apiClient, repo.RepoHost(), "PATCH", apiPath, body)
280				return err
281			})
282		}
283	
284		if len(opts.AddTopics) > 0 || len(opts.RemoveTopics) > 0 {
285			g.Go(func() error {
286				// opts.topicsCache gets populated in interactive mode
287				if !opts.InteractiveMode {
288					var err error
289					opts.topicsCache, err = getTopics(ctx, opts.HTTPClient, repo)
290					if err != nil {
291						return err
292					}
293				}
294				oldTopics := set.NewStringSet()
295				oldTopics.AddValues(opts.topicsCache)
296	
297				newTopics := set.NewStringSet()
298				newTopics.AddValues(opts.topicsCache)
299				newTopics.AddValues(opts.AddTopics)
300				newTopics.RemoveValues(opts.RemoveTopics)
301	
302				if oldTopics.Equal(newTopics) {
303					return nil
304				}
305				return setTopics(ctx, opts.HTTPClient, repo, newTopics.ToSlice())
306			})
307		}
308	
309		err := g.Wait()
310		if err != nil {
311			return err
312		}
313	
314		if opts.IO.IsStdoutTTY() {
315			cs := opts.IO.ColorScheme()
316			fmt.Fprintf(opts.IO.Out,
317				"%s Edited repository %s\n",
318				cs.SuccessIcon(),
319				ghrepo.FullName(repo))
320		}
321	
322		return nil
323	}
