325	func interactiveChoice(p iprompter, r *api.Repository) ([]string, error) {
326		options := []string{
327			optionDefaultBranchName,
328			optionDescription,
329			optionHomePageURL,
330			optionIssues,
331			optionMergeOptions,
332			optionProjects,
333			// TODO: GitHub Enterprise Server does not support has_discussions yet
334			// optionDiscussions,
335			optionTemplateRepo,
336			optionTopics,
