355	func interactiveRepoEdit(opts *EditOptions, r *api.Repository) error {
356		for _, v := range r.RepositoryTopics.Nodes {
357			opts.topicsCache = append(opts.topicsCache, v.Topic.Name)
358		}
359		p := opts.Prompter
360		choices, err := interactiveChoice(p, r)
361		if err != nil {
362			return err
363		}
364		for _, c := range choices {
365			switch c {
366			case optionDescription:
367				answer, err := p.Input("Description of the repository", r.Description)
368				if err != nil {
369					return err
370				}
371				opts.Edits.Description = &answer
372			case optionHomePageURL:
373				a, err := p.Input("Repository home page URL", r.HomepageURL)
374				if err != nil {
375					return err
376				}
377				opts.Edits.Homepage = &a
378			case optionTopics:
379				addTopics, err := p.Input("Add topics?(csv format)", "")
380				if err != nil {
381					return err
382				}
383				if len(strings.TrimSpace(addTopics)) > 0 {
384					opts.AddTopics = parseTopics(addTopics)
385				}
386	
387				if len(opts.topicsCache) > 0 {
388					selected, err := p.MultiSelect("Remove Topics", nil, opts.topicsCache)
389					if err != nil {
390						return err
391					}
392					for _, i := range selected {
393						opts.RemoveTopics = append(opts.RemoveTopics, opts.topicsCache[i])
394					}
395				}
396			case optionDefaultBranchName:
397				name, err := p.Input("Default branch name", r.DefaultBranchRef.Name)
398				if err != nil {
399					return err
400				}
401				opts.Edits.DefaultBranch = &name
402			case optionWikis:
403				c, err := p.Confirm("Enable Wikis?", r.HasWikiEnabled)
404				if err != nil {
405					return err
406				}
407				opts.Edits.EnableWiki = &c
408			case optionIssues:
409				a, err := p.Confirm("Enable Issues?", r.HasIssuesEnabled)
