516	func getTopics(ctx context.Context, httpClient *http.Client, repo ghrepo.Interface) ([]string, error) {
517		apiPath := fmt.Sprintf("repos/%s/%s/topics", repo.RepoOwner(), repo.RepoName())
518		req, err := http.NewRequestWithContext(ctx, "GET", ghinstance.RESTPrefix(repo.RepoHost())+apiPath, nil)
519		if err != nil {
520			return nil, err
521		}
522	
523		// "mercy-preview" is still needed for some GitHub Enterprise versions
524		req.Header.Set("Accept", "application/vnd.github.mercy-preview+json")
525		res, err := httpClient.Do(req)
526		if err != nil {
527			return nil, err
528		}
529		if res.StatusCode != http.StatusOK {
530			return nil, api.HandleHTTPError(res)
531		}
532	
533		var responseData struct {
534			Names []string `json:"names"`
535		}
536		dec := json.NewDecoder(res.Body)
537		err = dec.Decode(&responseData)
538		return responseData.Names, err
539	}
