104	func prStatus(cmd *cobra.Command, args []string) error {
105		ctx := contextForCommand(cmd)
106		apiClient, err := apiClientForContext(ctx)
107		if err != nil {
108			return err
109		}
110	
111		baseRepo, err := determineBaseRepo(apiClient, cmd, ctx)
112		if err != nil {
113			return err
114		}
115	
116		repoOverride, _ := cmd.Flags().GetString("repo")
117		currentPRNumber, currentPRHeadRef, err := prSelectorForCurrentBranch(ctx, baseRepo)
118	
119		if err != nil && repoOverride == "" && err.Error() != "git: not on any branch" {
120			return fmt.Errorf("could not query for pull request for current branch: %w", err)
121		}
122	
123		// the `@me` macro is available because the API lookup is ElasticSearch-based
124		currentUser := "@me"
125		prPayload, err := api.PullRequests(apiClient, baseRepo, currentPRNumber, currentPRHeadRef, currentUser)
126		if err != nil {
127			return err
128		}
129	
130		out := colorableOut(cmd)
131	
132		fmt.Fprintln(out, "")
133		fmt.Fprintf(out, "Relevant pull requests in %s\n", ghrepo.FullName(baseRepo))
134		fmt.Fprintln(out, "")
135	
136		printHeader(out, "Current branch")
137		currentPR := prPayload.CurrentPR
138		currentBranch, _ := ctx.Branch()
139		if currentPR != nil && currentPR.State != "OPEN" && prPayload.DefaultBranch == currentBranch {
140			currentPR = nil
141		}
142		if currentPR != nil {
143			printPrs(out, 1, *currentPR)
144		} else if currentPRHeadRef == "" {
145			printMessage(out, "  There is no current branch")
146		} else {
147			printMessage(out, fmt.Sprintf("  There is no pull request associated with %s", utils.Cyan("["+currentPRHeadRef+"]")))
148		}
149		fmt.Fprintln(out)
150	
151		printHeader(out, "Created by you")
152		if prPayload.ViewerCreated.TotalCount > 0 {
153			printPrs(out, prPayload.ViewerCreated.TotalCount, prPayload.ViewerCreated.PullRequests...)
154		} else {
155			printMessage(out, "  You have no open pull requests")
156		}
157		fmt.Fprintln(out)
158	
159		printHeader(out, "Requesting a code review from you")
160		if prPayload.ReviewRequested.TotalCount > 0 {
161			printPrs(out, prPayload.ReviewRequested.TotalCount, prPayload.ReviewRequested.PullRequests...)
162		} else {
163			printMessage(out, "  You have no pull requests to review")
164		}
165		fmt.Fprintln(out)
166	
167		return nil
168	}
