170	func prList(cmd *cobra.Command, args []string) error {
171		ctx := contextForCommand(cmd)
172		apiClient, err := apiClientForContext(ctx)
173		if err != nil {
174			return err
175		}
176	
177		baseRepo, err := determineBaseRepo(apiClient, cmd, ctx)
178		if err != nil {
179			return err
180		}
181	
182		limit, err := cmd.Flags().GetInt("limit")
183		if err != nil {
184			return err
185		}
186		state, err := cmd.Flags().GetString("state")
187		if err != nil {
188			return err
189		}
190		baseBranch, err := cmd.Flags().GetString("base")
191		if err != nil {
192			return err
193		}
194		labels, err := cmd.Flags().GetStringSlice("label")
195		if err != nil {
196			return err
197		}
198		assignee, err := cmd.Flags().GetString("assignee")
199		if err != nil {
200			return err
201		}
202	
203		var graphqlState []string
204		switch state {
205		case "open":
206			graphqlState = []string{"OPEN"}
207		case "closed":
208			graphqlState = []string{"CLOSED", "MERGED"}
209		case "merged":
210			graphqlState = []string{"MERGED"}
211		case "all":
212			graphqlState = []string{"OPEN", "CLOSED", "MERGED"}
213		default:
214			return fmt.Errorf("invalid state: %s", state)
215		}
216	
217		params := map[string]interface{}{
218			"owner": baseRepo.RepoOwner(),
219			"repo":  baseRepo.RepoName(),
220			"state": graphqlState,
221		}
222		if len(labels) > 0 {
223			params["labels"] = labels
224		}
225		if baseBranch != "" {
226			params["baseBranch"] = baseBranch
227		}
228		if assignee != "" {
229			params["assignee"] = assignee
230		}
231	
232		listResult, err := api.PullRequestList(apiClient, params, limit)
233		if err != nil {
234			return err
235		}
236	
237		hasFilters := false
238		cmd.Flags().Visit(func(f *pflag.Flag) {
239			switch f.Name {
240			case "state", "label", "base", "assignee":
241				hasFilters = true
242			}
243		})
244	
245		title := listHeader(ghrepo.FullName(baseRepo), "pull request", len(listResult.PullRequests), listResult.TotalCount, hasFilters)
246		// TODO: avoid printing header if piped to a script
247		fmt.Fprintf(colorableErr(cmd), "\n%s\n\n", title)
248	
249		table := utils.NewTablePrinter(cmd.OutOrStdout())
250		for _, pr := range listResult.PullRequests {
251			prNum := strconv.Itoa(pr.Number)
252			if table.IsTTY() {
253				prNum = "#" + prNum
254			}
255			table.AddField(prNum, nil, colorFuncForPR(pr))
256			table.AddField(replaceExcessiveWhitespace(pr.Title), nil, nil)
257			table.AddField(pr.HeadLabel(), nil, utils.Cyan)
258			table.EndRow()
259		}
260		err = table.Render()
261		if err != nil {
262			return err
263		}
264	
265		return nil
266	}
