268	func prStateTitleWithColor(pr api.PullRequest) string {
269		prStateColorFunc := colorFuncForPR(pr)
270		if pr.State == "OPEN" && pr.IsDraft {
271			return prStateColorFunc(strings.Title(strings.ToLower("Draft")))
272		}
273		return prStateColorFunc(strings.Title(strings.ToLower(pr.State)))
274	}
