283	// colorFuncForState returns a color function for a PR/Issue state
284	func colorFuncForState(state string) func(string) string {
285		switch state {
286		case "OPEN":
287			return utils.Green
288		case "CLOSED":
289			return utils.Red
290		case "MERGED":
291			return utils.Magenta
292		default:
293			return nil
294		}
295	}
