29	return nil, nil, fmt.Errorf("could not determine base repo: %w", err)
30	}
31	
32	// If there are no args see if we can guess the PR from the current branch
33	if len(args) == 0 {
34	pr, err := prForCurrentBranch(ctx, apiClient, repo)
35	return pr, repo, err
36	} else {
37	prString := args[0]
38	// Next see if the prString is a number and use that to look up the url
39	pr, err := prFromNumberString(ctx, apiClient, repo, prString)
40	if pr != nil || err != nil {
41	return pr, repo, err
42	}
43	
44	// Last see if it is a branch name
45	pr, err = api.PullRequestForBranch(apiClient, repo, "", prString)
46	return pr, repo, err
