58	func prFromURL(ctx context.Context, apiClient *api.Client, s string) (*api.PullRequest, ghrepo.Interface, error) {
59	r := regexp.MustCompile(`^https://github\.com/([^/]+)/([^/]+)/pull/(\d+)`)
60	if m := r.FindStringSubmatch(s); m != nil {
61	repo := ghrepo.New(m[1], m[2])
62	prNumberString := m[3]
63	pr, err := prFromNumberString(ctx, apiClient, repo, prNumberString)
64	return pr, repo, err
65	}
