70	func prForCurrentBranch(ctx context.Context, apiClient *api.Client, repo ghrepo.Interface) (*api.PullRequest, error) {
71	prHeadRef, err := ctx.Branch()
72	if err != nil {
73	return nil, err
74	}
75	
