77	
78	// the branch is configured to merge a special PR head ref
79	prHeadRE := regexp.MustCompile(`^refs/pull/(\d+)/head$`)
80	if m := prHeadRE.FindStringSubmatch(branchConfig.MergeRef); m != nil {
81	return prFromNumberString(ctx, apiClient, repo, m[1])
