85	if branchConfig.RemoteURL != nil {
86	// the branch merges from a remote specified by URL
87	if r, err := ghrepo.FromURL(branchConfig.RemoteURL); err == nil {
88	branchOwner = r.RepoOwner()
89	}
90	} else if branchConfig.RemoteName != "" {
91	// the branch merges from a remote specified by name
92	rem, _ := ctx.Remotes()
93	if r, err := rem.FindByName(branchConfig.RemoteName); err == nil {
94	branchOwner = r.RepoOwner()
95	}
96	}
97	
98	if branchOwner != "" {
99	if strings.HasPrefix(branchConfig.MergeRef, "refs/heads/") {
100	prHeadRef = strings.TrimPrefix(branchConfig.MergeRef, "refs/heads/")
101	}
102	// prepend `OWNER:` if this branch is pushed to a fork
103	if !strings.EqualFold(branchOwner, repo.RepoOwner()) {
104	prHeadRef = fmt.Sprintf("%s:%s", branchOwner, prHeadRef)
105	}
106	}
107	
108	return api.PullRequestForBranch(apiClient, repo, "", prHeadRef)
