76	/// The top-level entry point for single-threaded search. This recursively
77	/// steps through the file list (current directory by default) and searches
78	/// each file sequentially.
79	fn search(args: &Args) -> Result<bool> {
80	let started_at = Instant::now();
81	let quit_after_match = args.quit_after_match()?;
82	let subject_builder = args.subject_builder();
83	let mut stats = args.stats()?;
84	let mut searcher = args.search_worker(args.stdout())?;
85	let mut matched = false;
86	let mut searched = false;
87	
88	for result in args.walker()? {
89	let subject = match subject_builder.build_from_result(result) {
90	Some(subject) => subject,
91	None => continue,
92	};
93	searched = true;
94	let search_result = match searcher.search(&subject) {
95	Ok(search_result) => search_result,
96	Err(err) => {
97	// A broken pipe means graceful termination.
98	if err.kind() == io::ErrorKind::BrokenPipe {
99	break;
100	}
101	err_message!("{}: {}", subject.path().display(), err);
102	continue;
103	}
104	};
