184	        let mut conflicts = Conflicts::new();
185	        for arg_id in matcher
186	            .arg_names()
187	            .filter(|arg_id| matcher.contains_explicit(arg_id) && self.p.app.find(arg_id).is_some())
188	        {
189	            debug!("Validator::validate_conflicts::iter: id={:?}", arg_id);
190	            let conflicts = conflicts.gather_conflicts(self.p.app, matcher, arg_id);
191	            self.build_conflict_err(arg_id, &conflicts, matcher)?;
192	        }
193	
194	        Ok(())
195	    }
196	
197	    fn validate_exclusive(&self, matcher: &ArgMatcher) -> ClapResult<()> {
198	        debug!("Validator::validate_exclusive");
199	        let args_count = matcher.arg_names().count();
200	        matcher
201	            .arg_names()
202	            .filter_map(|name| {
203	                debug!("Validator::validate_exclusive:iter:{:?}", name);
204	                self.p
205	                    .app
206	                    .find(name)
207	                    // Find `arg`s which are exclusive but also appear with other args.
208	                    .filter(|&arg| arg.is_set(ArgSettings::Exclusive) && args_count > 1)
209	            })
210	            // Throw an error for the first conflict found.
211	            .try_for_each(|arg| {
212	                Err(Error::argument_conflict(
213	                    self.p.app,
214	                    arg,
215	                    Vec::new(),
216	                    Usage::new(self.p.app, &self.p.required).create_usage_with_title(&[]),
217	                ))
218	            })
219	    }
220	
221	    fn build_conflict_err(
222	        &self,
223	        name: &Id,
224	        conflict_ids: &[Id],
225	        matcher: &ArgMatcher,
226	    ) -> ClapResult<()> {
227	        if conflict_ids.is_empty() {
228	            return Ok(());
229	        }
230	
231	        debug!("Validator::build_conflict_err: name={:?}", name);
232	        let mut seen = std::collections::HashSet::new();
233	        let conflicts = conflict_ids
234	            .iter()
235	            .flat_map(|c_id| {
236	                if self.p.app.find_group(c_id).is_some() {
237	                    self.p.app.unroll_args_in_group(c_id)
238	                } else {
239	                    vec![c_id.clone()]
240	                }
241	            })
242	            .filter_map(|c_id| {
243	                seen.insert(c_id.clone()).then(|| {
244	                    let c_arg = self.p.app.find(&c_id).expect(INTERNAL_ERROR_MSG);
245	                    c_arg.to_string()
246	                })
247	            })
248	            .collect();
249	
250	        let former_arg = self.p.app.find(name).expect(INTERNAL_ERROR_MSG);
251	        let usg = self.build_conflict_err_usage(matcher, conflict_ids);
252	        Err(Error::argument_conflict(
253	            self.p.app, former_arg, conflicts, usg,
254	        ))
255	    }
256	
257	    fn build_conflict_err_usage(&self, matcher: &ArgMatcher, conflicting_keys: &[Id]) -> String {
258	        let used_filtered: Vec<Id> = matcher
259	            .arg_names()
260	            .filter(|key| !conflicting_keys.contains(key))
261	            .cloned()
262	            .collect();
263	        let required: Vec<Id> = used_filtered
264	            .iter()
265	            .filter_map(|key| self.p.app.find(key))
266	            .flat_map(|arg| arg.requires.iter().map(|item| &item.1))
267	            .filter(|key| !used_filtered.contains(key) && !conflicting_keys.contains(key))
268	            .chain(used_filtered.iter())
269	            .cloned()
270	            .collect();
271	        Usage::new(self.p.app, &self.p.required).create_usage_with_title(&required)
272	    }
273	
274	    fn gather_requirements(&mut self, matcher: &ArgMatcher) {
275	        debug!("Validator::gather_requirements");
276	        for name in matcher.arg_names() {
277	            debug!("Validator::gather_requirements:iter:{:?}", name);
278	            if let Some(arg) = self.p.app.find(name) {
279	                for req in self
280	                    .p
281	                    .app
282	                    .unroll_requirements_for_arg(&arg.id, Some(matcher))
283	                {
284	                    self.p.required.insert(req);
285	                }
286	            } else if let Some(g) = self.p.app.find_group(name) {
287	                debug!("Validator::gather_requirements:iter:{:?}:group", name);
288	                for r in &g.requires {
289	                    self.p.required.insert(r.clone());
290	                }
291	            }
292	        }
293	    }
294	
295	    fn validate_matched_args(&self, matcher: &ArgMatcher) -> ClapResult<()> {
296	        debug!("Validator::validate_matched_args");
297	        matcher.iter().try_for_each(|(name, ma)| {
298	            debug!(
299	                "Validator::validate_matched_args:iter:{:?}: vals={:#?}",
300	                name,
301	                ma.vals_flatten()
302	            );
303	            if let Some(arg) = self.p.app.find(name) {
304	                self.validate_arg_num_vals(arg, ma)?;
305	                self.validate_arg_values(arg, ma, matcher)?;
306	                self.validate_arg_num_occurs(arg, ma)?;
307	            }
308	            Ok(())
309	        })
310	    }
311	
312	    fn validate_arg_num_occurs(&self, a: &Arg, ma: &MatchedArg) -> ClapResult<()> {
313	        debug!(
314	            "Validator::validate_arg_num_occurs: {:?}={}",
315	            a.name,
316	            ma.get_occurrences()
317	        );
318	        // Occurrence of positional argument equals to number of values rather
319	        // than number of grouped values.
320	        if ma.get_occurrences() > 1
321	            && !a.is_set(ArgSettings::MultipleOccurrences)
322	            && !a.is_positional()
323	        {
324	            // Not the first time, and we don't allow multiples
325	            return Err(Error::unexpected_multiple_usage(
326	                self.p.app,
327	                a,
328	                Usage::new(self.p.app, &self.p.required).create_usage_with_title(&[]),
329	            ));
330	        }
331	        if let Some(max_occurs) = a.max_occurs {
332	            debug!(
333	                "Validator::validate_arg_num_occurs: max_occurs set...{}",
334	                max_occurs
335	            );
336	            let occurs = ma.get_occurrences() as usize;
337	            if occurs > max_occurs {
338	                return Err(Error::too_many_occurrences(
339	                    self.p.app,
340	                    a,
341	                    max_occurs,
342	                    occurs,
343	                    Usage::new(self.p.app, &self.p.required).create_usage_with_title(&[]),
344	                ));
345	            }
346	        }
347	
348	        Ok(())
349	    }
350	
351	    fn validate_arg_num_vals(&self, a: &Arg, ma: &MatchedArg) -> ClapResult<()> {
352	        debug!("Validator::validate_arg_num_vals");
353	        if let Some(num) = a.num_vals {
354	            let total_num = ma.num_vals();
355	            debug!("Validator::validate_arg_num_vals: num_vals set...{}", num);
356	            let should_err = if a.is_set(ArgSettings::MultipleOccurrences) {
357	                total_num % num != 0
358	            } else {
359	                num != total_num
360	            };
361	            if should_err {
362	                debug!("Validator::validate_arg_num_vals: Sending error WrongNumberOfValues");
363	                return Err(Error::wrong_number_of_values(
364	                    self.p.app,
365	                    a,
366	                    num,
367	                    if a.is_set(ArgSettings::MultipleOccurrences) {
368	                        total_num % num
369	                    } else {
370	                        total_num
371	                    },
372	                    Usage::new(self.p.app, &self.p.required).create_usage_with_title(&[]),
373	                ));
374	            }
375	        }
376	        if let Some(num) = a.max_vals {
377	            debug!("Validator::validate_arg_num_vals: max_vals set...{}", num);
378	            if ma.num_vals() > num {
379	                debug!("Validator::validate_arg_num_vals: Sending error TooManyValues");
380	                return Err(Error::too_many_values(
381	                    self.p.app,
382	                    ma.vals_flatten()
383	                        .last()
384	                        .expect(INTERNAL_ERROR_MSG)
385	                        .to_str()
386	                        .expect(INVALID_UTF8)
387	                        .to_string(),
388	                    a.to_string(),
389	                    Usage::new(self.p.app, &self.p.required).create_usage_with_title(&[]),
390	                ));
391	            }
392	        }
393	        let min_vals_zero = if let Some(num) = a.min_vals {
394	            debug!("Validator::validate_arg_num_vals: min_vals set: {}", num);
395	            if ma.num_vals() < num && num != 0 {
396	                debug!("Validator::validate_arg_num_vals: Sending error TooFewValues");
397	                return Err(Error::too_few_values(
398	                    self.p.app,
399	                    a,
400	                    num,
401	                    ma.num_vals(),
402	                    Usage::new(self.p.app, &self.p.required).create_usage_with_title(&[]),
403	                ));
404	            }
405	            num == 0
406	        } else {
407	            false
408	        };
409	        // Issue 665 (https://github.com/clap-rs/clap/issues/665)
410	        // Issue 1105 (https://github.com/clap-rs/clap/issues/1105)
411	        if a.is_set(ArgSettings::TakesValue) && !min_vals_zero && ma.all_val_groups_empty() {
412	            return Err(Error::empty_value(
413	                self.p.app,
414	                &a.possible_vals
415	                    .iter()
416	                    .filter_map(PossibleValue::get_visible_name)
417	                    .collect::<Vec<_>>(),
418	                a,
419	                Usage::new(self.p.app, &self.p.required).create_usage_with_title(&[]),
420	            ));
421	        }
422	        Ok(())"}]

