81	@Test
82	public void testRemovesOlderSegmentsWhenWriteOnReopenedDLQContainingExpiredSegments() throws IOException {
83	final Event event = DeadLetterQueueReaderTest.createEventWithConstantSerializationOverhead(Collections.emptyMap());
84	event.setField("message", DeadLetterQueueReaderTest.generateMessageContent(32479));
85	
86	final Clock pointInTimeFixedClock = Clock.fixed(Instant.parse("2022-02-22T10:20:30.00Z"), ZoneId.of("Europe/Rome"));
87	final ForwardableClock fakeClock = new ForwardableClock(pointInTimeFixedClock);
88	// given DLQ with first segment filled of expired events
89	prepareDLQWithFirstSegmentOlderThanRetainPeriod(event, fakeClock, Duration.ofDays(2));
90	
91	// Exercise
92	final long prevQueueSize;
93	final long beheadedQueueSize;
94	try (DeadLetterQueueWriter writeManager = DeadLetterQueueWriter
95	.newBuilder(dir, 10 * MB, 1 * GB, Duration.ofSeconds(1))
96	.retentionTime(Duration.ofDays(2))
97	.clock(fakeClock)
98	.build()) {
99	prevQueueSize = writeManager.getCurrentQueueSize();
100	assertEquals("Queue size is composed of one just one empty file with version byte", VERSION_SIZE, prevQueueSize);
101	
102	// write new entry that trigger clean of age retained segment
103	DLQEntry entry = new DLQEntry(event, "", "", String.format("%05d", 320), DeadLetterQueueReaderTest.constantSerializationLengthTimestamp(System.currentTimeMillis()));
104	// when a new write happens in a reopened queue
105	writeManager.writeEntry(entry);
106	beheadedQueueSize = writeManager.getCurrentQueueSize();
107	assertEquals("No event is expired after reopen of DLQ", 0, writeManager.getExpiredEvents());
108	}
109	
110	// then the age policy must remove the expired segments
111	assertEquals("Write should push off the age expired segments", VERSION_SIZE + BLOCK_SIZE, beheadedQueueSize);
112	}
