114	private void prepareDLQWithFirstSegmentOlderThanRetainPeriod(Event event, ForwardableClock fakeClock, Duration retainedPeriod) throws IOException {
115	final Duration littleMoreThanRetainedPeriod = retainedPeriod.plusMinutes(1);
116	long startTime = fakeClock.instant().minus(littleMoreThanRetainedPeriod).toEpochMilli();
117	int messageSize = 0;
118	try (DeadLetterQueueWriter writeManager = DeadLetterQueueWriter
119	.newBuilder(dir, 10 * MB, 1 * GB, Duration.ofSeconds(1))
120	.retentionTime(retainedPeriod)
121	.clock(fakeClock)
122	.build()) {
123	
124	// 320 generates 10 Mb of data
125	for (int i = 0; i < EVENTS_TO_FILL_A_SEGMENT; i++) {
126	DLQEntry entry = new DLQEntry(event, "", "", String.format("%05d", i), DeadLetterQueueReaderTest.constantSerializationLengthTimestamp(startTime++));
127	final int serializationLength = entry.serialize().length;
128	assertEquals("setup: serialized entry size...", serializationLength + RECORD_HEADER_SIZE, BLOCK_SIZE);
129	messageSize += serializationLength;
130	writeManager.writeEntry(entry);
131	}
132	assertThat(messageSize, is(greaterThan(BLOCK_SIZE)));
133	}
