226	public void testDLQWriterCloseRemovesExpiredSegmentWhenCurrentWriterIsUntouched() throws IOException {
227	final Event event = DeadLetterQueueReaderTest.createEventWithConstantSerializationOverhead(
228	Collections.singletonMap("message", "Not so important content"));
229	
230	// write some data in the new segment
231	final Clock pointInTimeFixedClock = Clock.fixed(Instant.now(), ZoneId.of("Europe/Rome"));
232	final ForwardableClock fakeClock = new ForwardableClock(pointInTimeFixedClock);
233	
234	Duration retainedPeriod = Duration.ofDays(1);
235	long startTime = fakeClock.instant().toEpochMilli();
236	try (DeadLetterQueueWriter writeManager = DeadLetterQueueWriter
237	.newBuilderWithoutFlusher(dir, 10 * MB, 1 * GB)
238	.retentionTime(retainedPeriod)
239	.clock(fakeClock)
240	.build()) {
241	
242	DLQEntry entry = new DLQEntry(event, "", "", "00001", DeadLetterQueueReaderTest.constantSerializationLengthTimestamp(startTime));
243	writeManager.writeEntry(entry);
244	}
245	
246	Set<String> segments = listFileNames(dir);
247	assertEquals("Once closed the just written segment, only 1 file must be present", Set.of("1.log"), segments);
248	
249	// move forward 3 days, so that the first segment becomes eligible to be deleted by the age retention policy
250	fakeClock.forward(Duration.ofDays(3));
251	try (DeadLetterQueueWriter writeManager = DeadLetterQueueWriter
252	.newBuilderWithoutFlusher(dir, 10 * MB, 1 * GB)
253	.retentionTime(retainedPeriod)
254	.clock(fakeClock)
255	.build()) {
256	// leave it untouched
257	assertTrue(writeManager.isOpen());
258	
259	// close so that it should clean the expired segments, close in implicitly invoked by try-with-resource statement
260	}
261	
262	Set<String> actual = listFileNames(dir);
263	assertThat("Age expired segment is removed", actual, not(hasItem("1.log")));
264	}
