27	* can be nested within.
28	*/
29	public interface NamespacedMetric extends Metric {
30	/**
31	* Writes an absolute value to the {@code metric}.
32	*
33	* @param metric metric to write value to
34	* @param value value to write
35	*/
36	void gauge(String metric, Object value);
37	
38	/**
39	* Creates a counter with the name {@code metric}.
40	*
41	* @param metric name of the counter
42	* @return an instance tracking a counter metric allowing easy incrementing and resetting
43	*/
44	CounterMetric counter(String metric);
45	
46	/**
47	* Increment the {@code metric} metric by 1.
48	*
49	* @param metric metric to increment
50	*/
51	void increment(String metric);
52	
53	/**
54	* Increment the {@code metric} by {@code delta}.
55	*
56	* @param metric metric to increment
57	* @param delta amount to increment by
58	*/
59	void increment(String metric, int delta);
60	
61	/**
62	* Times the {@code callable} and returns its value and increments the
63	* {@code metric} with the time taken.
64	*
65	* @param metric metric to increment
66	* @param callable callable to time
67	* @param <T> return type of the {@code callable}
68	* @return the return value from the {@code callable}
69	*/
70	<T> T time(String metric, Supplier<T> callable);
