80	/**
81	* Retrieves each namespace component that makes up this metric.
82	*
83	* @return the namespaces this metric is nested within
84	*/
85	String[] namespaceName();
86	
87	/**
88	* Gets Logstash's root metric namespace.
89	*
90	* @return the root namespace
91	*/
92	Metric root();
93	}
