40	/**
41	* Wraps a {@link AbstractNamespacedMetricExt} that represents a nested namespace and adds
42	* metrics and other namespaces to it.
43	*/
44	public class NamespacedMetricImpl implements NamespacedMetric {
45	private final ThreadContext threadContext;
46	private final AbstractNamespacedMetricExt metrics;
47	
48	public NamespacedMetricImpl(final ThreadContext threadContext, final AbstractNamespacedMetricExt metrics) {
49	this.threadContext = threadContext;
50	this.metrics = metrics;
51	}
52	
53	@Override
54	public void gauge(final String key, final Object value) {
55	this.metrics.gauge(this.threadContext, this.getSymbol(key), Rubyfier.deep(this.threadContext.getRuntime(), value));
56	}
57	
58	@Override
59	public CounterMetric counter(final String metric) {
60	return new CounterMetricImpl(this.threadContext, this.metrics, metric);
61	}
62	
63	@Override
64	public NamespacedMetric namespace(final String... key) {
65	final IRubyObject[] rubyfiedKeys = Stream.of(key)
66	.map(this::getSymbol)
67	.toArray(IRubyObject[]::new);
68	
69	return new NamespacedMetricImpl(
70	this.threadContext,
71	this.metrics.namespace(this.threadContext, RubyArray.newArray(this.threadContext.getRuntime(), rubyfiedKeys))
72	);
73	}
74	
75	@Override
76	public void increment(final String key) {
77	this.metrics.increment(this.threadContext, new IRubyObject[] { this.getSymbol(key) });
78	}
79	
80	@Override
81	public void increment(final String key, final int amount) {
82	this.metrics.increment(this.threadContext, new IRubyObject[] {
83	this.getSymbol(key),
84	this.convert(amount)
85	});
86	}
87	
88	@Override
89	public <T> T time(final String key, final Supplier<T> callable) {
90	final long start = System.nanoTime();
91	final T ret = callable.get();
92	final long end = System.nanoTime();
93	this.reportTime(key, TimeUnit.NANOSECONDS.toMillis(end - start));
94	return ret;
95	}
96	
97	@Override
98	public void reportTime(final String key, final long duration) {
99	this.metrics.reportTime(this.threadContext, this.getSymbol(key), this.convert(duration));
100	}
101	
102	@Override
103	public String[] namespaceName() {
104	final List<String> names = new ArrayList<>();
105	
106	for (final Object o : this.metrics.namespaceName(this.threadContext)) {
107	if (o instanceof RubyObject) {
108	names.add(((RubyObject) o).to_s().toString());
109	}
110	}
111	
112	return names.toArray(new String[0]);
113	}
114	
115	@Override
116	public Metric root() {
117	return new RootMetricImpl(this.threadContext, this.metrics.root(this.threadContext));
118	}
119	
120	private RubySymbol getSymbol(final String s) {
121	return this.threadContext.getRuntime().newSymbol(s);
122	}
123	
124	private IRubyObject convert(final Object o) {
125	return Rubyfier.deep(this.threadContext.getRuntime(), o);
126	}
