62	* {@link FileChannel#write(ByteBuffer)} and {@link CRC32#update(ByteBuffer)} calls.
63	*/
64	private final ByteBuffer buffer = ByteBuffer.allocateDirect(BUFFER_SIZE);
65	
66	private final CRC32 crc32 = new CRC32();
67	
68	private final boolean retry;
69	
70	private static final String HEAD_CHECKPOINT = "checkpoint.head";
71	private static final String TAIL_CHECKPOINT = "checkpoint.";
72	private final Path dirPath;
73	
74	public FileCheckpointIO(Path dirPath) {
75	this(dirPath, false);
76	}
77	
78	public FileCheckpointIO(Path dirPath, boolean retry) {
79	this.dirPath = dirPath;
80	this.retry = retry;
81	}
82	
83	@Override
84	public Checkpoint read(String fileName) throws IOException {
85	return read(
86	ByteBuffer.wrap(Files.readAllBytes(dirPath.resolve(fileName)))
87	);
88	}
89	
90	@Override
91	public Checkpoint write(String fileName, int pageNum, int firstUnackedPageNum, long firstUnackedSeqNum, long minSeqNum, int elementCount) throws IOException {
92	Checkpoint checkpoint = new Checkpoint(pageNum, firstUnackedPageNum, firstUnackedSeqNum, minSeqNum, elementCount);
93	write(fileName, checkpoint);
94	return checkpoint;
95	}
96	
97	@Override
98	public void write(String fileName, Checkpoint checkpoint) throws IOException {
99	write(checkpoint, buffer);
100	buffer.flip();
101	final Path tmpPath = dirPath.resolve(fileName + ".tmp");
102	try (FileOutputStream out = new FileOutputStream(tmpPath.toFile())) {
103	out.getChannel().write(buffer);
104	out.getFD().sync();
105	}
106	
107	try {
108	Files.move(tmpPath, dirPath.resolve(fileName), StandardCopyOption.ATOMIC_MOVE);
109	} catch (IOException ex) {
110	if (retry) {
111	try {
112	logger.error("Retrying after exception writing checkpoint: " + ex);
113	Thread.sleep(500);
114	Files.move(tmpPath, dirPath.resolve(fileName), StandardCopyOption.ATOMIC_MOVE);
115	} catch (IOException | InterruptedException ex2) {
116	logger.error("Aborting after second exception writing checkpoint: " + ex2);
117	throw ex;
118	}
119	} else {
120	logger.error("Error writing checkpoint: " + ex);
121	throw ex;
122	}
123	}
124	}
125	
126	@Override
127	public void purge(String fileName) throws IOException {
128	Path path = dirPath.resolve(fileName);
129	Files.delete(path);
130	}
131	
132	// @return the head page checkpoint file name
133	@Override
134	public String headFileName() {
135	return HEAD_CHECKPOINT;
136	}
137	
138	// @return the tail page checkpoint file name for given page number
139	@Override
140	public String tailFileName(int pageNum) {
141	return TAIL_CHECKPOINT + pageNum;
142	}
143	
144	public static Checkpoint read(ByteBuffer data) throws IOException {
145	int version = (int) data.getShort();
146	// TODO - build reader for this version
147	int pageNum = data.getInt();
148	int firstUnackedPageNum = data.getInt();
149	long firstUnackedSeqNum = data.getLong();
150	long minSeqNum = data.getLong();
151	int elementCount = data.getInt();
152	final CRC32 crc32 = new CRC32();
153	crc32.update(data.array(), 0, BUFFER_SIZE - Integer.BYTES);
154	int calcCrc32 = (int) crc32.getValue();
155	int readCrc32 = data.getInt();
156	if (readCrc32 != calcCrc32) {
157	throw new IOException(String.format("Checkpoint checksum mismatch, expected: %d, actual: %d", calcCrc32, readCrc32));
158	}
159	if (version != Checkpoint.VERSION) {
160	throw new IOException("Unknown file format version: " + version);
161	}
162	
163	return new Checkpoint(pageNum, firstUnackedPageNum, firstUnackedSeqNum, minSeqNum, elementCount);
164	}
165	
166	private void write(Checkpoint checkpoint, ByteBuffer buf) {
167	crc32.reset();
168	buf.clear();
169	buf.putShort((short)Checkpoint.VERSION);
170	buf.putInt(checkpoint.getPageNum());
171	buf.putInt(checkpoint.getFirstUnackedPageNum());
172	buf.putLong(checkpoint.getFirstUnackedSeqNum());
173	buf.putLong(checkpoint.getMinSeqNum());
174	buf.putInt(checkpoint.getElementCount());
175	buf.flip();
176	crc32.update(buf);
177	buf.position(BUFFER_SIZE - Integer.BYTES).limit(BUFFER_SIZE);
178	buf.putInt((int)crc32.getValue());
179	}
180	}
