70	public void capture() {
71	final Capture newestHead = doCapture();
72	final Capture previousHead = head.getAndSet(newestHead);
73	instant.getAndAccumulate(previousHead, (current, given) -> {
74	// keep our current value if the given one is less than ~100ms older than our newestHead
75	// this is naive and when captures happen too frequently without relief can result in
76	// our "current" window growing indefinitely, but we are shipping with a 5s cadence
77	// and shouldn't hit this edge-case in practice.
78	return (newestHead.calculateCapturePeriod(given).toMillis() > 100) ? given : current;
79	});
80	}
