120	/**
121	*
122	* @param baseline a non-null {@link Capture} from which to compare.
123	* @return an {@link OptionalDouble} that will be non-empty IFF we have sufficient information
124	*         to calculate a finite rate of change of the numerator relative to the denominator.
125	*/
126	OptionalDouble calculateRate(final Capture baseline) {
127	Objects.requireNonNull(baseline, "baseline");
128	if (baseline == this) { return OptionalDouble.empty(); }
129	
130	final double deltaNumerator = this.numerator.doubleValue() - baseline.numerator.doubleValue();
131	final double deltaDenominator = this.denominator.doubleValue() - baseline.denominator.doubleValue();
132	
133	// divide-by-zero safeguard
134	if (deltaDenominator == 0.0) { return OptionalDouble.empty(); }
135	
136	// To prevent the appearance of false-precision, we round to 3 decimal places.
137	return OptionalDouble.of(BigDecimal.valueOf(deltaNumerator)
138	.divide(BigDecimal.valueOf(deltaDenominator), 3, RoundingMode.HALF_UP)
139	.doubleValue());
140	}
