144	* @return an {@link OptionalDouble} that will be non-empty IFF we have sufficient information
145	*         to calculate a finite rate of change of the numerator relative to the denominator.
146	*/
147	OptionalDouble calculateRate(final Supplier<Capture> possibleBaseline) {
148	return Optional.ofNullable(possibleBaseline.get())
149	.map(this::calculateRate)
150	.orElseGet(OptionalDouble::empty);
151	}
152	
153	Duration calculateCapturePeriod(final Capture baseline) {
154	return Duration.ofNanos(Math.subtractExact(this.nanoTimestamp, baseline.nanoTimestamp));
155	}
