20	package org.logstash.instrument.metrics;
21	
22	import java.math.BigDecimal;
23	import java.util.Objects;
24	import java.util.concurrent.TimeUnit;
25	import java.util.function.LongSupplier;
26	
27	/**
28	* The {@link UptimeMetric} is an auto-advancing {@link Metric} whose value
29	* represents the amount of time since instantiation. It can be made to track the
30	* advancement of the clock in one of several {@link TimeUnit}s.
31	*/
32	public class UptimeMetric extends AbstractMetric<Long> {
33	private final LongSupplier nanoTimeSupplier;
34	private final long startNanos;
35	
36	public enum ScaleUnits {
37	NANOSECONDS(0),
38	MICROSECONDS(3),
39	MILLISECONDS(6),
40	SECONDS(9),
41	;
42	
43	private final int nanoRelativeDecimalShift;
44	
45	ScaleUnits(final int nanoRelativeDecimalShift) {
46	this.nanoRelativeDecimalShift = nanoRelativeDecimalShift;
47	}
48	}
49	private final TimeUnit timeUnit;
50	
51	/**
52	* Constructs an {@link UptimeMetric} whose name is "uptime_in_millis" and whose units are milliseconds
53	*/
54	public UptimeMetric() {
55	this(MetricKeys.UPTIME_IN_MILLIS_KEY.asJavaString());
56	}
57	
58	/**
59	* Constructs an {@link UptimeMetric} with the provided name.
60	* @param name the name of the metric, which is used by our metric store, API retrieval, etc.
61	*/
62	public UptimeMetric(final String name) {
63	this(name, System::nanoTime);
64	}
65	
66	UptimeMetric(final String name, final LongSupplier nanoTimeSupplier) {
67	this(name, nanoTimeSupplier, nanoTimeSupplier.getAsLong(), TimeUnit.MILLISECONDS);
68	}
69	
70	private UptimeMetric(final String name, final LongSupplier nanoTimeSupplier, final long startNanos, final TimeUnit timeUnit) {
71	super(Objects.requireNonNull(name, "name"));
72	this.nanoTimeSupplier = Objects.requireNonNull(nanoTimeSupplier, "nanoTimeSupplier");
73	this.timeUnit = Objects.requireNonNull(timeUnit, "timeUnit");
74	this.startNanos = Objects.requireNonNull(startNanos, "startNanos");
75	}
76	
77	/**
78	* @return the number of {@link TimeUnit}s that have elapsed
79	*         since this {@link UptimeMetric} was instantiated
80	*/
81	@Override
82	public Long getValue() {
83	return this.timeUnit.convert(getElapsedNanos(), TimeUnit.NANOSECONDS);
84	}
85	
86	long getElapsedNanos() {
87	return this.nanoTimeSupplier.getAsLong() - this.startNanos;
88	}
89	
90	/**
91	* @return the {@link MetricType}{@code .COUNTER_LONG} associated with
92	*         long-valued metrics that only-increment, for use in Monitoring data structuring.
93	*/
94	@Override
95	public MetricType getType() {
96	return MetricType.COUNTER_LONG;
97	}
98	
99	/**
100	* @return the {@link TimeUnit} associated with this {@link UptimeMetric}.
101	*/
102	public TimeUnit getTimeUnit() {
103	return timeUnit;
104	}
105	
106	/**
107	* Constructs a _copy_ of this {@link UptimeMetric} with a new name and timeUnit, but whose
108	* uptime is tracking from the same instant as this instance.
109	*
110	* @param name the new metric's name (typically includes units)
111	* @param timeUnit the new metric's units
112	* @return a _copy_ of this {@link UptimeMetric}.
113	*/
114	public UptimeMetric withTimeUnit(final String name, final TimeUnit timeUnit) {
115	return new UptimeMetric(name, this.nanoTimeSupplier, this.startNanos, timeUnit);
116	}
117	
118	/**
119	* Constructs a _view_ into this {@link UptimeMetric} whose value is a decimal number
120	* containing subunit precision.
121	*
122	* @param name the name of the metric
123	* @param scaleUnits the desired scale
124	* @return a {@link BigDecimal} representing the whole-and-fractional number
125	*         of {@link ScaleUnits} that have elapsed.
126	*/
127	public ScaledView withUnitsPrecise(final String name, final ScaleUnits scaleUnits) {
128	return new ScaledView(name, this::getElapsedNanos, scaleUnits.nanoRelativeDecimalShift);
129	}
130	
131	/**
132	* {@code name} defaults to something vaguely descriptive.
133	* Useful when the caller doesn't need the metric name.
134	*
135	* @see UptimeMetric#withUnitsPrecise(String, ScaleUnits)
136	*/
137	public ScaledView withUnitsPrecise(final ScaleUnits scaleUnits) {
138	final String name = String.format("%s_scaled_to_%s", getName(), scaleUnits.name());
139	return this.withUnitsPrecise(name, scaleUnits);
140	}
141	
142	static class ScaledView implements Metric<Number> {
143	private final String name;
144	private final int nanoRelativeDecimalShift;
145	private final LongSupplier elapsedNanosSupplier;
146	
147	ScaledView(final String name,
148	final LongSupplier elapsedNanosSupplier,
149	final int nanoRelativeDecimalShift) {
150	this.name = name;
151	this.nanoRelativeDecimalShift = nanoRelativeDecimalShift;
152	this.elapsedNanosSupplier = elapsedNanosSupplier;
153	}
154	
155	@Override
156	public String getName() {
157	return this.name;
158	}
159	
160	@Override
161	public MetricType getType() {
162	return MetricType.COUNTER_DECIMAL;
163	}
164	
165	@Override
166	public BigDecimal getValue() {
167	return BigDecimal.valueOf(elapsedNanosSupplier.getAsLong(), nanoRelativeDecimalShift);
168	}
169	}
170	}
