2	
3	import org.junit.Test;
4	import org.logstash.instrument.metrics.counter.LongCounter;
5	
6	import java.time.Duration;
7	import java.time.Instant;
8	import java.util.List;
9	import java.util.Map;
10	
11	import static org.junit.Assert.*;
12	import static org.logstash.instrument.metrics.FlowMetric.CURRENT_KEY;
13	import static org.logstash.instrument.metrics.FlowMetric.LIFETIME_KEY;
14	
15	public class FlowMetricTest {
16	@Test
17	public void testBaselineFunctionality() {
18	final ManualAdvanceClock clock = new ManualAdvanceClock(Instant.now());
19	final LongCounter numeratorMetric = new LongCounter(MetricKeys.EVENTS_KEY.asJavaString());
20	final Metric<Number> denominatorMetric = new UptimeMetric("uptime", clock::nanoTime).withUnitsPrecise(UptimeMetric.ScaleUnits.SECONDS);
21	final FlowMetric instance = new FlowMetric(clock::nanoTime, "flow", numeratorMetric, denominatorMetric);
22	
23	final Map<String, Double> ratesBeforeCaptures = instance.getValue();
24	assertTrue(ratesBeforeCaptures.isEmpty());
25	
26	// 5 seconds pass, during which 1000 events are processed
27	clock.advance(Duration.ofSeconds(5));
28	numeratorMetric.increment(1000);
29	instance.capture();
30	final Map<String, Double> ratesAfterFirstCapture = instance.getValue();
31	assertFalse(ratesAfterFirstCapture.isEmpty());
32	assertEquals(Map.of(LIFETIME_KEY, 200.0, CURRENT_KEY, 200.0), ratesAfterFirstCapture);
33	
34	// 5 more seconds pass, during which 2000 more events are processed
35	clock.advance(Duration.ofSeconds(5));
36	numeratorMetric.increment(2000);
37	instance.capture();
38	final Map<String, Double> ratesAfterSecondCapture = instance.getValue();
39	assertFalse(ratesAfterSecondCapture.isEmpty());
40	assertEquals(Map.of(LIFETIME_KEY, 300.0, CURRENT_KEY, 400.0), ratesAfterSecondCapture);
41	
42	// 30 seconds pass, during which 11700 more events are seen by our numerator
43	for (Integer eventCount : List.of(1883, 2117, 1901, 2299, 1608, 1892)) {
44	clock.advance(Duration.ofSeconds(5));
45	numeratorMetric.increment(eventCount);
46	instance.capture();
47	}
48	final Map<String, Double> ratesAfterNthCapture = instance.getValue();
49	assertFalse(ratesAfterNthCapture.isEmpty());
50	assertEquals(Map.of(LIFETIME_KEY, 367.5, CURRENT_KEY, 378.4), ratesAfterNthCapture);
51	
52	// less than half a second passes, during which 0 events are seen by our numerator.
53	// when our two most recent captures are very close together, we want to make sure that
54	// we continue to provide _meaningful_ metrics, namely that:
55	// (a) our CURRENT_KEY and LIFETIME_KEY account for newest capture, and
56	// (b) our CURRENT_KEY does not report _only_ the delta since the very-recent capture
57	clock.advance(Duration.ofMillis(10));
58	instance.capture();
59	final Map<String, Double> ratesAfterSmallAdvanceCapture = instance.getValue();
60	assertFalse(ratesAfterNthCapture.isEmpty());
61	assertEquals(Map.of(LIFETIME_KEY, 367.408, CURRENT_KEY, 377.645), ratesAfterSmallAdvanceCapture);
62	}
63	}
