2	
3	import java.time.Clock;
4	import java.time.Duration;
5	import java.time.Instant;
6	import java.time.ZoneId;
7	import java.time.temporal.ChronoUnit;
8	import java.util.Objects;
9	import java.util.concurrent.atomic.AtomicReference;
10	
11	class ManualAdvanceClock extends Clock {
12	private final ZoneId zoneId;
13	private final AtomicReference<Instant> currentInstant;
14	private final Instant zeroInstant;
15	
16	public ManualAdvanceClock(final Instant currentInstant, final ZoneId zoneId) {
17	this(currentInstant, new AtomicReference<>(currentInstant), zoneId);
18	}
19	
20	public ManualAdvanceClock(final Instant currentInstant) {
21	this(currentInstant, null);
22	}
23	
24	private ManualAdvanceClock(final Instant zeroInstant, final AtomicReference<Instant> currentInstant, final ZoneId zoneId) {
25	this.zeroInstant = zeroInstant;
26	this.currentInstant = currentInstant;
27	this.zoneId = Objects.requireNonNullElseGet(zoneId, ZoneId::systemDefault);
28	}
29	
30	@Override
31	public ZoneId getZone() {
32	return this.zoneId;
33	}
34	
35	@Override
36	public Clock withZone(ZoneId zone) {
37	return new ManualAdvanceClock(this.zeroInstant, this.currentInstant, zone);
38	}
39	
40	@Override
41	public Instant instant() {
42	return currentInstant.get();
43	}
44	
45	/**
46	* @return an only-incrementing long value, meant as a drop-in replacement
47	*         for {@link System#nanoTime()}, using this {@link ManualAdvanceClock}
48	*         as the time source, and carrying the same constraints.
49	*/
50	public long nanoTime() {
51	return zeroInstant.until(instant(), ChronoUnit.NANOS);
52	}
53	
54	public void advance(final Duration duration) {
55	if (duration.isZero()) {
56	return;
57	}
58	if (duration.isNegative()) {
59	throw new IllegalArgumentException("duration must not be negative");
60	}
61	this.currentInstant.updateAndGet(previous -> previous.plus(duration));
62	}
63	}
