620	    optimize `cPar` for a given input (`srcSize` and `dictSize`).
621	    mostly downsizing to reduce memory consumption and initialization latency.
622	    Both `srcSize` and `dictSize` are optional (use 0 if unknown).
623	    Note : cPar is considered validated at this stage. Use ZSTD_checkCParams() to ensure that condition. */
624	ZSTD_compressionParameters ZSTD_adjustCParams_internal(ZSTD_compressionParameters cPar, unsigned long long srcSize, size_t dictSize)
625	{
626	    static const U64 minSrcSize = 513; /* (1<<9) + 1 */
627	    static const U64 maxWindowResize = 1ULL << (ZSTD_WINDOWLOG_MAX-1);
628	    assert(ZSTD_checkCParams(cPar)==0);
629	
630	    if (dictSize && (srcSize+1<2) /* srcSize unknown */ )
631	        srcSize = minSrcSize;  /* presumed small when there is a dictionary */
632	    else if (srcSize == 0)
633	        srcSize = ZSTD_CONTENTSIZE_UNKNOWN;  /* 0 == unknown : presumed large */
634	
635	    /* resize windowLog if input is small enough, to use less memory */
636	    if ( (srcSize < maxWindowResize)
637	      && (dictSize < maxWindowResize) )  {
638	        U32 const tSize = (U32)(srcSize + dictSize);
639	        static U32 const hashSizeMin = 1 << ZSTD_HASHLOG_MIN;
640	        U32 const srcLog = (tSize < hashSizeMin) ? ZSTD_HASHLOG_MIN :
641	                            ZSTD_highbit32(tSize-1) + 1;
642	        if (cPar.windowLog > srcLog) cPar.windowLog = srcLog;
643	    }
644	    if (cPar.hashLog > cPar.windowLog) cPar.hashLog = cPar.windowLog;
645	    {   U32 const cycleLog = ZSTD_cycleLog(cPar.chainLog, cPar.strategy);
646	        if (cycleLog > cPar.windowLog)
647	            cPar.chainLog -= (cycleLog - cPar.windowLog);
648	    }
649	
650	    if (cPar.windowLog < ZSTD_WINDOWLOG_ABSOLUTEMIN)
651	        cPar.windowLog = ZSTD_WINDOWLOG_ABSOLUTEMIN;  /* required for frame header */
652	
653	    return cPar;
654	}
