656	ZSTD_compressionParameters ZSTD_adjustCParams(ZSTD_compressionParameters cPar, unsigned long long srcSize, size_t dictSize)
657	{
658	    cPar = ZSTD_clampCParams(cPar);
659	    return ZSTD_adjustCParams_internal(cPar, srcSize, dictSize);
