2130	static size_t ZSTD_loadDictionaryContent(ZSTD_matchState_t* ms, ZSTD_CCtx_params const* params, const void* src, size_t srcSize)
2131	{
2132	    const BYTE* const ip = (const BYTE*) src;
2133	    const BYTE* const iend = ip + srcSize;
2134	    ZSTD_compressionParameters const* cParams = &params->cParams;
