2147	    switch(params->cParams.strategy)
2148	    {
2149	    case ZSTD_fast:
2150	        ZSTD_fillHashTable(ms, cParams, iend);
2151	        break;
2152	    case ZSTD_dfast:
2153	        ZSTD_fillDoubleHashTable(ms, cParams, iend);
2154	        break;
2155	
2156	    case ZSTD_greedy:
2157	    case ZSTD_lazy:
2158	    case ZSTD_lazy2:
2159	        if (srcSize >= HASH_READ_SIZE)
2160	            ZSTD_insertAndFindFirstIndex(ms, cParams, iend-HASH_READ_SIZE);
2161	        break;
2162	
2163	    case ZSTD_btlazy2:   /* we want the dictionary table fully sorted */
2164	    case ZSTD_btopt:
2165	    case ZSTD_btultra:
2166	        if (srcSize >= HASH_READ_SIZE)
